\label{lem:reduction}
For $x,y\in\mathbb C^n$,
\begin{equation}\label{eq:pw-polygon}
\mathrm{PW}_{\mathrm{SO}(2)}^2(X,Y)=\frac{\|x\|^2+\|y\|^2}{n}-\frac2n\max_{z\in\mathcal{P}(\bar x,y)}|z|.
\end{equation}
A vertex $z_{\sigma^\star}$ attains the maximum. Its matching $\sigma^\star$ is optimal, with angle $-\operatorname{Arg} z_{\sigma^\star}$ when the correlation is nonzero. If the maximum modulus is zero, every angle is optimal. For $\mathrm{O}(2)$, take the larger maximum over $\mathcal{P}(\bar x,y)$ and $\mathcal{P}(\bar x,\bar y)$.

\label{lem:jump}
Let $(a,b)$ be generic with $n\ge3$, and let the edge $e$ of $\mathcal{P}$ lead counterclockwise from $z_\sigma$ to $z_\tau$, with outward unit normal $u$ and cycle length $L_e$. For $L_e\ge3$, the polygon $\Gamma_e$ is simple and counterclockwise, and $I_e$ counts the off-cycle points $b_{j_0}$ strictly inside it. Set $I_e=0$ for $L_e=2$. Then
\begin{equation}\label{eq:jump}
\Psi(\tau,u)-\Psi(\sigma,u)=\pi(L_e-1+2I_e).
\end{equation}

\label{lem:counting}
For $n\ge3$ and generic $(a,b)$, every $\Gamma_e$ with $L_e\ge3$ is a simple, counterclockwise polygon, and
\begin{equation}\label{eq:counting}
\sum_{\text{edges }e\text{ of }\mathcal{P}}\big(L_e-1+2I_e\big)=n(n-1),
\end{equation}
with $L_e$ and $I_e$ as in \Cref{lem:jump}.

We order $a_1<\dots<a_n$, express each coefficient through its consecutive differences, and regroup the terms to obtain Abel's summation identity
\begin{equation}\label{eq:abel-summation}
z_\sigma=a_1\sum_jb_j+\sum_{k=2}^n(a_k-a_{k-1})\sum_{l\ge k}b_{\sigma(l)}.
\end{equation}
In a direction $u$, all terms are maximized together by sending the largest row indices to the points $b_j$ with the largest projections $\operatorname{Re}(\bar ub_j)$. Since support functions add under Minkowski sums, $\mathcal{P}$ is a translate of a Minkowski sum of positive multiples of the polygons $Q_h=\operatorname{conv}\{\sum_{j\in S}b_j:|S|=h\}$, $1\le h\le n-1$. For $n\ge3$, each pair of points exchanges its order of projection twice during a full turn. Because the pairwise differences are non-parallel, only one pair ties at a time, and the two tied points are adjacent in that order. Their exchange changes exactly one top-$h$ subset and thus gives one edge of one $Q_h$. These $n(n-1)$ edges have distinct normals and remain edges of the Minkowski sum, so $\mathcal{P}$ has that many vertices. For $n=2$, the two distinct correlations form a segment. The full construction and the edge count are proved in \Cref{app:tightness}.

\label{lem:arc-interpolation}
Let $F=\min_{M\in\mathcal M}g_M$ be the affine extension over a nonempty finite matching family. For $0<h_\theta<\pi/2$ and $I=[\mu-h_\theta,\mu+h_\theta]$, let $\mathcal T_I$ be the triangle enclosing $\mathcal U_I=\{u(\theta):\theta\in I\}$, and let $\ell$ interpolate its three oracle values. Then
\begin{equation}\label{eq:arc-bound-chain}
 \min_{v\in\operatorname{vert}\mathcal T_I}F(v)
 \le\min_{u\in\mathcal U_I}\ell(u)
 \le\min_{u\in\mathcal U_I}F(u).
\end{equation}
If one matching attains all three oracle values, then $F=\ell$ on $\mathcal T_I$,
including when other matchings tie.

\label{lem:common-translation}
Use the pose convention $R_z(\theta)x_i+t-y_j$, reversing the point-set names in \eqref{eq:pw}.
Let $\mathcal A_{\rm sel}$ be a nonempty finite, pose-independent family of selections of
exactly $k\ge1$ pairs from planar or three-dimensional point sets. Define
\begin{equation}\label{eq:corrected-gravity-objective}
\begin{split}
 F(u,t)=\min_{A_{\rm sel}\in\mathcal A_{\rm sel}}\sum_{(i,j)\in A_{\rm sel}}\big[&
 \|\widehat R(u)x_i+t-y_j\|^2\\
 &+(1-\|u\|^2)\|x_{i,xy}\|^2\big].
\end{split}
\end{equation}
For planar inputs, $x_{i,xy}=x_i$. Let $B$ be an axis-aligned translation box
with center $c_B$, nonnegative halfwidths $\boldsymbol h_t$, and corners $t_\nu$, retaining duplicate
corners when necessary. Let a nondegenerate triangle enclose the physical yaw arc $\mathcal U_I$
for an interval $I$, and let $\ell_\nu$ interpolate $F(\cdot,t_\nu)$ at its three vertices.
Then
\begin{equation}\label{eq:common-translation-guarantee}
 \min_\nu\min_{u\in\mathcal U_I}\ell_\nu(u)-k\|\boldsymbol h_t\|^2
 \le\min_{u\in\mathcal U_I,\,t\in B}F(u,t).
\end{equation}
Selections may repeat targets, as in fixed-count trimmed nearest neighbors.

\label{prop:joint-gravity-accuracy}
Let $\mathcal E$ be a finite set of pairs of rational three-dimensional points and let
$\mathcal A_{\rm sel}$ be a nonempty, globally fixed family of selections of exactly
$k\ge1$ pairs from $\mathcal E$. Assume an exact polynomial-time rational oracle for
affine minimization over $\mathcal A_{\rm sel}$. For unit scale, yaw, and translation in
a rational box $B$ of side lengths $\ell_j$, choose a rational bound
\begin{equation}\label{eq:gravity-grid-slope}
 \kappa_B\ge2k\max_{(i,j)\in \mathcal E}\sup_{t\in B}
 \|x_{i,xy}\|\,\|t_{xy}-y_{j,xy}\|.
\end{equation}
For rational $\varepsilon>0$, a feasible pose and an enclosing summed-objective
interval of width at most $\varepsilon$ can be obtained with at most
$128N_\theta\prod_{j=1}^3N_{t,j}$ oracle calls, where $N_\theta=\max\{1,\lceil2\sqrt{\kappa_B/\varepsilon}\rceil\}$ and
\begin{equation}\label{eq:gravity-grid-counts}
 N_{t,j}=\max\{1,\lceil\sqrt{3k\ell_j^2/(2\varepsilon)}\rceil\}.
\end{equation}
The count is $\mathcal O(\varepsilon^{-2})$ at fixed numerical scales.

\label{lem:quaternion-enclosure}
Let $\tilde q$ lie in the convex hull of nonzero raw quaternion vertices $\tilde q_a$ satisfying
$\tilde q_a^\top \tilde q_b>0$ for every pair, and put $q=\tilde q/\|\tilde q\|$. The matrices in
\eqref{eq:outer-quaternion} enclose $qq^\top$, that is, $qq^\top\in\operatorname{conv}\{B_{ab}:a\le b\}$. Consequently the support
$H$ in \eqref{eq:quaternion-support} satisfies
\begin{equation}\label{eq:face-bound}
 H(qq^\top)\le\min\{\max_{a\le b}H(B_{ab}),\lambda_{\max}(K(C_\tau))+\delta_\tau\}
\end{equation}
for every feasible permutation $\tau$, with $\delta_\tau$ as in
\eqref{eq:face-slack}. A common supporting permutation has $\delta_\tau=0$,
regardless of ties.

\label{lem:spatial-bound-reuse}
For a feasible square-assignment witness $\tau$, the quantities in
\eqref{eq:lifted-difference} satisfy $\eta_\tau\ge0$ and
\begin{equation}\label{eq:difference-bound-guarantee}
 H(Q)\le\langle K(C_\tau),Q\rangle_F+\eta_\tau\quad\text{for }Q\in\operatorname{conv}\{B_{ab}\}.
\end{equation}
For $N_{\rm query}$ vertices, construction and one assignment cost
$\mathcal O(N_{\rm query}n^2+n^3)$ operations and $\mathcal O(n^2)$ streamed storage.
Any prices in \eqref{eq:reused-dual} also give a valid support upper bound, $H(Q)\le H_{\rm dual}(Q;g)$;
a feasible matching attaining it is optimal. Row-complete rectangular matching
requires nonnegative column prices, and equality requires zero prices on unused
columns.

\emph{Distinct correlations.} For $\sigma\ne\tau$, the polynomial $z_\sigma-z_\tau=a^\top(P_\sigma-P_\tau)b$ is not identically zero: the coordinate vectors $a=e_i$, $b=e_j$ at a nonzero entry $(i,j)$ of $P_\sigma-P_\tau$ give a nonzero value. Thus (G1) fails only on a proper algebraic set.

\emph{Noncollinear triples.} For distinct $\sigma_1,\sigma_2,\sigma_3$, define $D_1=P_{\sigma_2}-P_{\sigma_1}$, $D_2=P_{\sigma_3}-P_{\sigma_1}$ and
$\Phi(a,b)=\operatorname{Im}\big(\overline{a^\top D_1b}\;a^\top D_2b\big)$. Collinearity is equivalent to $\Phi=0$, so we must show that $\Phi$ is not identically zero.
The matrices $D_1,D_2$ are nonzero and linearly independent. Their entries lie in $\{-1,0,1\}$, so any factor of proportionality would be $\pm1$; the factor $+1$ would identify $\sigma_2$ and $\sigma_3$, and the factor $-1$ would make $P_{\sigma_3}=2P_{\sigma_1}-P_{\sigma_2}$ contain an entry $2$.
Suppose that $\Phi\equiv0$. Taking $b=\beta_{\mathrm{test}}\in\mathbb R^n$ and $a=\alpha_{\mathrm{test}}'+\mathrm i\alpha_{\mathrm{test}}''$ with $\alpha_{\mathrm{test}}',\alpha_{\mathrm{test}}''\in\mathbb R^n$ gives
\begin{equation}
\begin{aligned}
\Phi={}&(\alpha_{\mathrm{test}}'^\top D_1\beta_{\mathrm{test}})(\alpha_{\mathrm{test}}''^\top D_2\beta_{\mathrm{test}})\\
&-(\alpha_{\mathrm{test}}''^\top D_1\beta_{\mathrm{test}})(\alpha_{\mathrm{test}}'^\top D_2\beta_{\mathrm{test}}).
\end{aligned}
\end{equation}
Since this vanishes for all $\alpha_{\mathrm{test}}'$ and $\alpha_{\mathrm{test}}''$, the vectors $D_1\beta_{\mathrm{test}}$ and $D_2\beta_{\mathrm{test}}$ are linearly dependent for every real $\beta_{\mathrm{test}}$. Taking $a$ real and $b$ complex shows in the same way that $\alpha_{\mathrm{test}}^\top D_1$ and $\alpha_{\mathrm{test}}^\top D_2$ are dependent for every real $\alpha_{\mathrm{test}}$.

\emph{Rank.} On the dense open set $\mathcal U_{\mathrm{lin}}=\{\beta_{\mathrm{test}}:D_2\beta_{\mathrm{test}}\ne0\}$, write $D_1\beta_{\mathrm{test}}=\eta_{\mathrm{lin}}(\beta_{\mathrm{test}})D_2\beta_{\mathrm{test}}$. If $D_2\beta_{\mathrm{test},1}$ and $D_2\beta_{\mathrm{test},2}$ are independent, comparing coefficients in
\begin{equation}
\begin{aligned}
&\eta_{\mathrm{lin}}(\beta_{\mathrm{test},1}+t\beta_{\mathrm{test},2})(D_2\beta_{\mathrm{test},1}+tD_2\beta_{\mathrm{test},2})\\
&\quad=\eta_{\mathrm{lin}}(\beta_{\mathrm{test},1})D_2\beta_{\mathrm{test},1}\\
&\qquad+t\eta_{\mathrm{lin}}(\beta_{\mathrm{test},2})D_2\beta_{\mathrm{test},2}
\end{aligned}
\end{equation}
gives $\eta_{\mathrm{lin}}(\beta_{\mathrm{test},1})=\eta_{\mathrm{lin}}(\beta_{\mathrm{test},2})$.
If $\operatorname{rank}D_2\ge2$, any two points of $\mathcal U_{\mathrm{lin}}$ can be compared through a third point whose image lies on neither of their image lines. Hence $\eta_{\mathrm{lin}}$ is constant on $\mathcal U_{\mathrm{lin}}$ and, by density, $D_1=\eta_{\mathrm{lin}} D_2$, which contradicts independence. Exchanging the roles of $D_1$ and $D_2$ excludes $\operatorname{rank}D_1\ge2$ in the same way, so the only remaining possibility is that both ranks are one. Write $D_l=c_lr_l^\top$ with nonzero factors. Choosing $\beta_{\mathrm{test}}$ outside both row kernels forces $c_1\parallel c_2$, and choosing $\alpha_{\mathrm{test}}$ nonorthogonal to both columns forces $r_1\parallel r_2$, which again contradicts independence. Thus $\Phi\not\equiv0$. The non-generic pairs lie in the finite union of the zero sets of these polynomials, which is a proper real-algebraic set and has measure zero.

\label{prop:total}
For generic $(a,b)$ with $n\ge3$, the jumps satisfy
\begin{equation}
\sum_{m=1}^{V}\Delta\Psi_m=\pi n(n-1).
\end{equation}

We unwrap the angles of the normals as $\varphi_0<\cdots<\varphi_V=\varphi_0+2\pi$, with $u_m=e^{\mathrm i\varphi_m}$. On $[\varphi_{m-1},\varphi_m]$, optimality keeps each $e^{-\mathrm i\varphi}\Delta z_{ik}(\sigma_m)$ in the closed right half-plane without the origin, where its principal argument decreases at unit speed. Hence $\Psi(\sigma_m,u_m)-\Psi(\sigma_m,u_{m-1})=-\binom n2(\varphi_m-\varphi_{m-1})$. Summing over $m$ and adding the jumps gives
\begin{equation}
\begin{aligned}
&\sum_m\big[\Psi(\sigma_{m+1},u_m)-\Psi(\sigma_m,u_{m-1})\big]\\
&\qquad=\sum_m\Delta\Psi_m-2\pi\binom n2.
\end{aligned}
\end{equation}
The left side telescopes to $0$, because the final normal direction and matching agree with the initial ones. The jumps therefore balance the continuous decrease over the full turn.

As in Step~5, points that slide along distinct edges of a simple polygon do not collide. Each summand of $\Theta$ is the principal angle from $\gamma_r-\gamma_s$ to $\gamma_{r+1}-\gamma_{s+1}$, because the segment that connects them avoids $0$. Thus $\Theta$ is continuous on the space $\mathcal S_L^+$ of simple counterclockwise $L$-gons with labeled vertices.
The cyclic shift of the vertices also fixes the value of $\Theta$ modulo a full turn:
\begin{equation}
\begin{aligned}
e^{\mathrm i\Theta}
&=\prod_{r<s}\frac{\gamma_{r+1}-\gamma_{s+1}}{\gamma_r-\gamma_s}
\Big/\Big|\prod_{r<s}\frac{\gamma_{r+1}-\gamma_{s+1}}{\gamma_r-\gamma_s}\Big|
\\
&=\operatorname{sgn}(c)=(-1)^{L-1},
\end{aligned}
\end{equation}
because permuting the points by the cyclic shift $c$ multiplies $\prod_{r<s}(\gamma_r-\gamma_s)$ by $\operatorname{sgn}(c)$. Thus $\Theta\in\pi(L-1)+2\pi\mathbb Z$, and $\Theta$ is locally constant on $\mathcal S_L^+$.
It remains to show that $\mathcal S_L^+$ is path-connected. By the convexification theorem of Connelly et~al.~\cite{connelly2003}, each polygon can be convexified continuously through simple polygons, with its orientation preserved. We translate the resulting convex polygon so that the origin lies in its interior. Its vertices are then $\rho_re^{\mathrm i\alpha_r}$ with increasing angles and consecutive gaps in $(0,\pi)$. Interpolating the radii to $1$ and the gaps to $2\pi/L$ keeps the gaps in $(0,\pi)$, so the polygon remains star-shaped about the origin, simple and counterclockwise. Finally we rotate the resulting regular polygon to a fixed reference. Continuity and local constancy then make the angle sum the same for every polygon in this space.
For the regular polygon $\gamma_r=e^{2\pi\mathrm ir/L}$ we have $\gamma_r(\zeta)-\gamma_s(\zeta)=(\gamma_r-\gamma_s)\big((1-\zeta)+\zeta e^{2\pi\mathrm i/L}\big)$, so each pair turns by $2\pi/L$ and $\Theta=\binom L2\frac{2\pi}L=\pi(L-1)$. Reversing the orientation negates $\Theta$.

We write $z=z_{\sigma_t}$, $z'=z_{\sigma_{t+1}}$, and $u=z/|z|$ for $z\ne0$. Optimality of the assignment gives
\begin{equation}
|z'|\ge\operatorname{Re}(\bar u z')\ge\operatorname{Re}(\bar u z)=|z|.
\end{equation}
Retention makes the second inequality strict whenever the matching changes, even if several matchings share a vertex. A matching is retained exactly when $\operatorname{Re}(\bar z(w-z))\le0$ for all $w\in\mathcal P$. A vertex of largest modulus satisfies this condition because $\operatorname{Re}(\bar zw)\le|z||w|\le|z|^2$. A nonzero initial vertex excludes zero thereafter and allows at most $V-1\le n(n-1)-1$ strict increases. An unchanged matching retains its correlation and direction and therefore remains fixed. Including the final check, there are at most $V$ assignment updates after the initialization.

For $N=1$ the set is a single point. Otherwise we replace each atom $x_i$ of positive weight by $N\alpha_i$ copies and each $y_j$ by $N\beta_j$ copies, which gives $\tilde x,\tilde y\in\mathbb C^N$. Aggregating a doubly stochastic matrix over the blocks of copies gives $N\pi$ for some $\pi\in\Pi(\alpha,\beta)$. Conversely, take any such transport plan and set $P_{IJ}=\pi_{ij}/(N\alpha_i\beta_j)$ for the copies $I$ of $x_i$ and $J$ of $y_j$. Its row sums are
\begin{equation}
\sum_J P_{IJ}=\sum_j\frac{N\beta_j\pi_{ij}}{N\alpha_i\beta_j}
=\frac{\sum_j\pi_{ij}}{\alpha_i}=1,
\end{equation}
and its column sums equal one in the same way. Thus the lifted matrix is doubly stochastic. The block $(i,j)$ sums to $N\pi_{ij}$, so
\begin{equation}
\frac1N\sum_{I,J}P_{IJ}\overline{\tilde x_I}\tilde y_J
=\sum_{i,j}\pi_{ij}\bar x_i y_j.
\end{equation}
The weighted polygon is consequently $\frac1N\mathcal P(\overline{\tilde x},\tilde y)$. Scaling does not change the number of vertices, and \Cref{thm:main} applies despite the repeated points.

In coordinates centered on the arc, the vertices of the triangle are $(c_h,-s_h)$, $(c_h,s_h)$ and $(1/c_h,0)$, with $c_h=\cos h_\theta>0$ and $s_h=\sin h_\theta>0$. Its chord and the two tangents at the endpoints enclose the arc. For the oracle values $f_-,f_+,f_A$ and $\bar f=(f_-+f_+)/2$, the interpolant is
\begin{equation}\label{eq:arc-interpolant-coefficients}
 \begin{gathered}
 \ell(u(\mu+\eta))=\alpha\cos\eta+\beta\sin\eta+\gamma,\\
 \alpha=\frac{f_A-\bar f}{1/c_h-c_h},\qquad
 \beta=\frac{f_+-f_-}{2s_h},\\
 \gamma=\bar f-\alpha c_h.
 \end{gathered}
\end{equation}
To minimize this sinusoid, we evaluate both endpoints and the angle $\operatorname{atan2}(\beta,\alpha)+\pi$ modulo $2\pi$ when it lies in $[-h_\theta,h_\theta]$; if $\alpha=\beta=0$, the value is the constant $\gamma$. The same minimization fits each returned matching. Concavity gives $F\ge\ell$ throughout the triangle, and the convex interpolation weights give $\ell\ge\min\{f_-,f_+,f_A\}$. These two inequalities prove \eqref{eq:arc-bound-chain}. If one matching $M$ attains all three queries, then $g_M=\ell$ and $F\le g_M$, hence equality. The oracle may return different optimizers under ties even when a common supporting matching exists; testing a retained witness at all three vertices verifies common support without requiring uniqueness.

The anchor construction gives a finite translation domain without knowledge of the matched subsets. For prescribed $k>0$ and a feasible cost $U$, an improving matching has an edge whose residual has norm at most $r=\sqrt{U/k}$. For every anchor $(i,j)$, we put $x'_a=x_a-x_i$, $y'_b=y_b-y_j$, and $e=t-x_i+R_z(\theta)y_j$. Then
\begin{equation}\label{eq:anchor-residual-identity}
 x_a-R_z(\theta)y_b-t=x'_a-R_z(\theta)y'_b-e.
\end{equation}
The forced anchor has residual $-e\in[-r,r]^3$. At least one selected edge of an improving matching can serve as this anchor, so the union over all anchors covers every improving solution. An optimum exists: each of the finitely many nonempty matchings allows the translation to be eliminated through its centroids, which leaves a compact yaw domain. For penalties, we use each $k$ with $U_k=U-\lambda(n+m-2k)\ge0$ and radius $r_k=\sqrt{U_k/k}$; a negative $U_k$ cannot improve $U$. The empty matching costs $\lambda(n+m)$.

For a residual-translation box with center $c_B$ and halfwidth vector $\boldsymbol h_t$, write $r_B^2=\|\boldsymbol h_t\|^2$ and $u=(\cos\theta,\sin\theta)$, and define
\begin{equation}\label{eq:joint-curvature-removal}
 h_M(u,e)=E_M(u,e)-k\|e-c_B\|^2.
\end{equation}
As in the conditional-yaw construction, the horizontal norms of the points are kept constant off the circle. Removing the common quadratic term in the translation makes $h_M$ affine in $u$ and affine in each component of $e$ separately, cross terms included, so it equals its product barycentric interpolant. At all 24 vertices, $\|e-c_B\|^2=r_B^2$, so the oracle value there is $\min_M E_M(v)-kr_B^2$.

For $f_v=\min_Mh_M(v)$ and any witness $W$ of size $k$, \eqref{eq:gravity-joint-slack} gives $h_M(v)\ge f_v\ge h_W(v)-\Delta_W$ for every competitor $M$. The product interpolation uses nonnegative weights, so it extends these vertex inequalities throughout the cell. Restoring the quadratic term gives
\begin{equation}\label{eq:joint-witness-bound-proof}
 \min_M E_M(u,e)\ge E_W(u,e)-\Delta_W.
\end{equation}
A witness that supports all vertices has $\Delta_W=0$, which gives equality and solves the cell by minimizing over its pose. The bound requires neither common support nor unique optimizers.

The grid controls two errors: the one from the quadratic term in the translation, and the one from replacing an exterior yaw query by a feasible sample. We divide each translation coordinate into $N_{t,j}$ equal intervals. We sample each quarter circle by
\begin{equation}\label{eq:rational-yaw-parameterization}
 p(\xi)=\frac{(1-\xi^2,2\xi)}{1+\xi^2},\qquad \xi=j/N_\theta,
\end{equation}
and rotate these samples through right angles. Adjacent endpoints $u_-,u_+$ have the rational tangent apex $(u_-+u_+)/(1+u_-^\top u_+)$. At each of the eight corners of a box, we query the two endpoints, their tangent apex, and the physical point at the midpoint of the parameter interval. The first three queries supply values for the lower bound, and the physical samples supply feasible values. Let $f_{\min}$ be the smallest queried value. \Cref{lem:common-translation} gives the lower bound $L=f_{\min}-k\|\boldsymbol h_t\|^2$. The minimum of the affine costs is $\kappa_B$-Lipschitz in the yaw coordinates.

To bound the second error, write $\delta=\xi_{j+1}-\xi_j\le1/N_\theta$ and $\phi(\xi)=2\arctan \xi$. The half-width $\alpha$ of the arc satisfies $\alpha\le\delta$ and $\alpha\le\pi/4$, since $|\phi'|\le2$. The angular midpoint differs from $\phi((\xi_j+\xi_{j+1})/2)$ by at most $\delta^2/2$, by $|\phi''|\le4$ and the error of midpoint interpolation. The apex has radius $\sec\alpha$, so its Euclidean distance to this physical sample is at most
\begin{equation}\label{eq:rational-apex-distance}
 \delta^2/2+(\sec\alpha-1)
 \le\delta^2/2+\alpha^2\le2/N_\theta^2.
\end{equation}
Here $\sec\alpha-1=(1-\cos\alpha)/\cos\alpha\le\alpha^2$ because $\cos\alpha\ge1/2$. If the smallest queried value occurs at an endpoint, that query is already physical and needs no projection. Thus the best sampled feasible value satisfies
\begin{equation}\label{eq:rational-grid-gap}
 U-L\le k\|\boldsymbol h_t\|^2+2\kappa_B/N_\theta^2\le\varepsilon.
\end{equation}
Taking the minima of the lower bounds and of the feasible values across cells preserves this gap. The number of queries is the number of grid cells times four quarters, eight corners and four evaluations. All query coordinates and costs are rational, and integer comparisons determine the grid counts. Ties and degenerate translation boxes remain valid.

Centering complete point sets uses the same centroids for every permutation. This eliminates the translation as $t=m_x-Rm_y$ and gives the centered residual $S-2\langle R,C_\sigma\rangle_F$. For a unit quaternion $q=(q_0,q_v)$ with $q_v\in\mathbb R^3$, we use the convention that, for any $b_{\rm rot}\in\mathbb R^3$,
\begin{equation}\label{eq:quaternion-rotation-formula}
 R(q)b_{\rm rot}=(q_0^2-\|q_v\|^2)b_{\rm rot}+2q_v(q_v^\top b_{\rm rot})+2q_0(q_v\mathbin\times b_{\rm rot}).
\end{equation}
Horn's quaternion matrix~\cite{horn1987} encodes the covariance score as a quadratic form:
\begin{equation}\label{eq:quaternion-covariance-matrix}
 \begin{gathered}
 K(C)=\begin{bmatrix}\operatorname{tr}C&c_{\rm cross}(C)^\top\\
 c_{\rm cross}(C)&C+C^\top-(\operatorname{tr}C)I_3\end{bmatrix},\\
 c_{\rm cross}(C)=(C_{32}-C_{23},C_{13}-C_{31},C_{21}-C_{12})^\top.
 \end{gathered}
\end{equation}
Expanding the rotation formula proves \eqref{eq:quaternion-score}. Any unit eigenvector for the largest eigenvalue, also under ties, maximizes the Rayleigh quotient and gives a proper rotation. Linearity of $K$ and convexity of $\lambda_{\max}$ prove that a vertex attains the maximum in \eqref{eq:se3-polytope}. The affine dimension is $r_Xr_Y\le9$ for the centered ranks $r_X,r_Y$: the matrices with four nonzero entries and zero row and column sums span the direction space of the Birkhoff polytope~\cite{brualdi1977}, and their images span the outer products of point differences. Repeated points and rank deficiency are included.

The adjoint converts a lifted quaternion query into ordinary assignment scores. For a symmetric query matrix $Q\in\mathbb S^4$, with $b_Q\in\mathbb R^3$ and $Q_{vv}\in\mathbb R^{3\times3}$, we write
\begin{equation}\label{eq:quaternion-adjoint}
 \begin{gathered}
 Q=\begin{bmatrix}Q_{00}&b_Q^\top\\b_Q&Q_{vv}\end{bmatrix},\\
 D(Q)=(Q_{00}-\operatorname{tr}Q_{vv})I_3+2Q_{vv}+2[b_Q]_\times,
 \end{gathered}
\end{equation}
where $[b_Q]_\times b_{\rm rot}=b_Q\mathbin\times b_{\rm rot}$. The identity $\langle D(Q),C\rangle_F=\langle Q,K(C)\rangle_F$ gives the scores $a_i^\top D(Q)b_j$ without forming a $4\times4$ matrix for each edge. Unit rank-one lifts give rotations; exterior queries require neither a positive semidefinite $Q$ nor a rotation $D(Q)$.

For rational inputs, rational support queries, reconstruction of the facets and algebraic comparison of eigenvalues give a finite exact reduction; arbitrary real inputs require ideal arithmetic. No polynomial bound on the number of facets follows.

The enclosure follows by expanding the normalized lift of a convex combination. We write $\tilde q=\sum_a\alpha_a\tilde q_a$, where $\alpha_a\ge0$ and $\sum_a\alpha_a=1$, and assume that all corner dot products are strictly positive. For $a\le b$, we define
\begin{equation}\label{eq:quaternion-lift-weights}
 \beta_{aa}=\frac{\alpha_a^2\|\tilde q_a\|^2}{\|\tilde q\|^2},\quad \beta_{ab}=\frac{2\alpha_a\alpha_b\tilde q_a^\top \tilde q_b}{\|\tilde q\|^2}\quad(a<b).
\end{equation}
These coefficients are nonnegative and sum to one. Expanding gives $qq^\top=\sum_{a\le b}\beta_{ab}B_{ab}$, which proves the enclosure. Convexity gives the bound by the largest vertex value and, for any matching $\tau$,
\begin{equation}\label{eq:quaternion-slack-proof}
 \begin{aligned}
 &H(qq^\top)-\langle K(C_\tau),qq^\top\rangle_F\\
 &\quad\le\sum_{a\le b}\beta_{ab}\big(H(B_{ab})-\langle K(C_\tau),B_{ab}\rangle_F\big)\\
 &\quad\le\delta_\tau.
 \end{aligned}
\end{equation}
Bounding the quadratic score of the witness itself by its largest eigenvalue proves \eqref{eq:face-bound}. Feasibility gives $\delta_\tau\ge0$, and common support makes it zero without uniqueness.

For the square lifted assignment problem, we fix a permutation $\tau$ and define $d^\tau$ and $\eta_\tau$ by \eqref{eq:lifted-difference}. At any convex combination $Q$ of the exterior matrices, linearity gives
\begin{equation}\label{eq:lifted-edge-difference-bound}
 A_{ij}(Q)-A_{i,\tau(i)}(Q)\le d_{ij}^\tau.
\end{equation}
Summing over a matching and maximizing gives $H(Q)-\langle K(C_\tau),Q\rangle_F\le\eta_\tau$, with $\eta_\tau\ge0$ because $d_{i,\tau(i)}^\tau=0$. If $\eta_\tau=0$, the witness is optimal throughout the enclosure. Its largest rotation score plus $\eta_\tau$ bounds the cell. The edgewise maxima can be attained at different exterior matrices, so even common support need not make this relaxation zero; support queries or feasible duals can tighten it.

Computing the edgewise maxima and then one assignment gives the stated work bound, and accumulating the maxima one matrix at a time gives the stated storage bound. Summing $f_i+g_{\sigma(i)}\ge A_{i,\sigma(i)}(Q)$ over a matching proves the dual upper bound defined in \eqref{eq:reused-dual}, and a feasible matching that attains this bound is optimal. Rectangular assignments in which every row is matched require nonnegative column prices, with zero prices on the unused columns for equality. Recomputing the row maxima restores dual feasibility, which permits the reuse of prices also after the old matching has ceased to be optimal. The prices may also be linear functions of the query that are obtained from paths of difference constraints: evaluating them and repairing the rows remains feasible, even though the paths need not stay optimal.

The queue represents the part of the search domain that can still contain an improving solution. For every live region we keep $L_\Omega\le\min_{p\in\Omega,M}E(M,p)$, together with a feasible incumbent of cost $U$. Discarded regions had $L_\Omega\ge U$, and a later decrease of $U$ cannot make them improving. Hence
\begin{equation}\label{eq:live-cover-interval}
 L=\min\{U,\min_{\Omega\text{ live}}L_\Omega\}\le E^*\le U,
\end{equation}
with $L=U$ for an empty queue. Feasible updates preserve this interval, also when the fitted pose lies outside the cell that generated it, and so do tightening, changes of priority and complete child covers. Children inherit the maximum of the parent's bound and their new bounds. Keeping the old record of a region until its evaluation or replacement is complete preserves the cover under interruption.

The initial residual bounds are zero for complete or prescribed-cardinality matching and $\lambda|n-m|$ for penalties. They cover all roots before any evaluation: the three yaw arcs, all anchors of the joint gravity search, or the 32 quaternion boxes. Complete matching can also use the score bound
\begin{equation}\label{eq:initial-covariance-bound}
 b_0=\sum_{i=1}^n r_i^\uparrow s_i^\uparrow,
 \qquad r_i=\|a_i\|,\quad s_j=\|b_j\|,
\end{equation}
with both sequences in increasing order. Edgewise Cauchy--Schwarz and the rearrangement inequality bound every assignment by $b_0$, which gives the residual bound $\max(0,S-2b_0)$.

A valid interval alone does not guarantee that the search finishes. Termination also requires progress: yaw arcs and the longest quaternion coordinates are bisected, and the joint gravity search must shrink the yaw and every active translation coordinate. Tightening must eventually yield to subdivision, and adaptive evaluations must retain a regional bound and feasible updates whose gap vanishes under refinement. The vanishing gaps follow from \Cref{app:gravity-accuracy} for conditional yaw, \Cref{app:joint-convergence} for joint gravity, and \Cref{app:quaternion-cover} for the quaternion search. An infinite tree with finitely many roots and finitely many children per node would contain an infinite path, along which progress makes the gap vanish. Once the gap of a least-bound cell is at most $\varepsilon$, its feasible value puts the global incumbent within $\varepsilon$ of the live lower bound, which prevents further subdivision. This contradiction proves finite termination without a budget. Beyond the count of \Cref{prop:gravity-accuracy} for conditional yaw, no polynomial bound on the number of regions follows.

With unknown translation, the covariance alone is insufficient, because the matched centroids vary. We instead collect the sufficient statistics of each matching,
\begin{equation}\label{eq:partial-moment-construction}
 \begin{gathered}
 k=|M|,\qquad \boldsymbol s_{X,M}=\sum_Mx_i,\qquad \boldsymbol s_{Y,M}=\sum_My_j,\\
 S_M=\sum_M(\|x_i\|^2+\|y_j\|^2),\qquad
 C_M=\sum_Mx_i y_j^\top
 \end{gathered}
\end{equation}
in a space of dimension at most 17. The vector moments are coordinate sums, not centroids. At fixed $R,t$, the residual is affine in these statistics:
\begin{equation}\label{eq:partial-moment-cost}
 S_M+k\|t\|^2-2\langle R,C_M\rangle_F-2t^\top \boldsymbol s_{X,M}+2t^\top R\boldsymbol s_{Y,M}.
\end{equation}
The penalty for unmatched points is also affine. Taking the infimum over $R,t$ gives a concave function, whose minimum over the finite hull of the statistics is attained at a vertex. Nonempty vertex matchings are evaluated by subset centering and proper rotation, and the empty matching is evaluated separately. Linear support queries are partial assignments. This vertex principle covers unequal cardinalities, unmatched points and full rigid motion.
